/**
 * 측정 방향 잠금·붙잡기 툴팁(3D 뷰어 코어 0.10.0 추론 잠금·나란함, 0.12.0 모서리 끝 선분 방향 잠금 — SketchUp의 추론 잠금을 따른다).
 * 코어 측정 모드가 상태와 판정을 가지고(setMeasureSnap({ inference: { lock, parallel } })·setMeasureInferenceLock·measureHoverLock),
 * 이 모듈은 앱 쪽 손잡이만 둔다.
 *
 * - 툴팁: 측정 중 커서 아래 붙잡을 점의 종류(끝점·중심·교차점·X축 방향·나란한 방향 …)를 그 점 오른쪽 아래에, 잠갔으면 "잠금"을 덧붙인다.
 *   코어가 그린 거리 글상자(measureLabelRect)와 겹치거나 3D 보기 밖으로 나가면 왼쪽 아래·오른쪽 위·왼쪽 위 차례로 옮긴다(placeTip).
 *   코어는 미리 보기를 그리기(rAF) 때 구하므로 키 뒤에는 다음 프레임에 읽는다(schedule). 포인터 이동은 코어 미리 보기 알림으로 맞춘다(101차). 글은 DOM이라 번역층이 옮긴다.
 *   97차: 마우스를 멈춘 채 재생으로 장면이 바뀌어(깎기 시뮬레이션 메시 바꾸기·재생 붙잡기 한도) 코어가 미리 보기를 다시 구할 때도 맞춘다.
 *   99차: 그 길 목록(97차 sceneChanged — 층 사건·한도)을 걷고 코어 0.103.0 onMeasureHoverChange(미리 보기 값이 바뀐 그림 뒤 한 번) 하나로 맞춘다(attach).
 *   100차: 카메라만 움직이면(휠·보기 키 F·1~7·카메라 움직임·3D 보기 크기) 코어는 미리 보기를 다시 구하지 않아(세계 점 그대로) 그 알림이 없다 —
 *   코어 onCameraChange에서 툴팁이 있을 때만 그 점을 다시 투영해 자리만 옮긴다(follow — 글은 그대로).
 *   104차: 코어 0.110.0부터 카메라가 멈춘 첫 그림에서 코어가 그 커서 자리에서 다시 구해 값이 바뀌면 그 알림이 한 번 온다(follow는 움직이는 동안과 앱 API 카메라 함수 뒤에 그대로).
 *   105차: 코어 0.111.0부터 빈 곳 위 커서(미리 보기 null)도 그 자리에 그대로면 카메라가 멈춘 그림·단면·겉모습 뒤 다시 구해, 형상이 오면 null 다음 그 값으로 그 알림이 한 번 온다(앱 코드는 그대로).
 *   101차: 코어 0.107.0부터 끌어온 점 목록이 바뀐 그림 뒤에도 그 미리 보기 알림이 와, 99차가 남긴 포인터 길(pointermove·pointerleave·pointerup → 두 프레임 뒤 update)을 걷었다(attach).
 *   112차: 코어 0.118.0부터 마우스 미리 보기 자리 후보를 Tab·Shift+Tab으로 돌린 동안만 미리 보기 값에 차례·수(cycle)가 실려 이름 뒤에 「2/4」를 붙이고(cycleOrder),
 *   같은 글을 가상 커서 알림 영역에 넣는다(sayCycle — 화면 읽기).
 *   158차: 찍은 점·끌어온 점이 없을 때 3D 보기가 받은 Esc는 툴팁을 거둔다(escTip — 같은 점·같은 글인 동안 다시 띄우지 않음, WCAG 1.4.13 닫을 수 있음).
 *   191차: 코어 글상자가 비키는 떠 있는 것(뷰 큐브·측정 띠·해석 판단 띠 — coverRects)도 비킨다(툴팁 z-index가 띠보다 높아 띠 글·버튼을 덮었다, WCAG 1.4.13·2.4.11).
 *   192차: 측정 띠 위 알림(showFlash — 띠 상자 밖)도 떠 있는 동안 그 목록에 넣어 툴팁·코어 글상자가 비키고, 뜨고 질 때 다시 놓는다(schedule).
 * - Shift: 코어가 누르는 순간 잠글 방향(measureHoverLock — 방향 추론(축·나란함·수직), 첫 점을 지나는 선분 위의 점 붙잡기면 그 선분 방향:
 *   모서리 끝에서 그 모서리를 따라 다른 끝을 가리킬 때)을 잠그고 떼면 푼다. 앱은 Shift를 누르고 뗄 때 툴팁·상태 줄만 다시 맞춘다.
 *   상태 줄·측정 띠는 잠글 방향이 있을 때만 "Shift로 X축 방향 잠그기"처럼 알리고, 없으면 화살표만 알린다(lockHint).
 * - 화살표(첫 점을 찍은 뒤, 둘째 점 방향을 잡는 동안): → X · ← Y · ↑ Z축, ↓ 지금 방향(없으면 첫 점 뒤 마지막으로 본 방향 — 코어). 같은 키로 푼다.
 *   203차: 가상 커서가 켜진 동안(화살표는 커서 옮기기)은 3D 보기가 받은 X·Y·Z가 같은 길로 그 축을 잠그고 푼다(axisKey — 잠근 축·푼 것은 가상 커서 알림 영역에).
 *   204차: 그 동안 L이 ↓와 같은 길로 지금 방향을 잠그고 푼다(Shift는 누르는 동안만이고 그동안 화살표는 커서 큰 걸음 — 눌러 잠가 두고 화살표로 잘게 옮기는 키).
 * - 측정 띠 잠금 단추(손가락 기기 — 넓은 화면에서는 띠가 숨는다): 방향을 잡는 동안만 보인다. 정밀 조준 중 다른 손가락으로 누르면 click이
 *   오지 않으므로 손가락·펜은 pointerdown에서 받는다. 잠글 방향이 없으면 띠 위에 알림을 띄우고, 잠금이 걸리면(어느 길로든) 그 알림만 거둔다.
 * - 원호 접선(13차): 첫 점이 원호 이동(G2/G3, 나선 포함)의 시작·끝이고 커서 아래 점이 그 원호 위(다른 끝 포함)면 Shift·↓·잠금 단추가
 *   그 끝의 접선 방향으로 잠근다(host.arcTangent — tangent.ts, 코어 setMeasureInferenceLock({ direction, kind: 'parallel' })).
 *   첫 점이 원호의 가운데 점(앱의 원호 가운데 점 붙잡기)이어도 그 점의 접선으로(14차), 원호 위 다른 자리(현 위 — 코어 모서리 붙잡기)면
 *   원호 위 가장 가까운 자리의 접선으로(15차 — 점은 코어 점 그대로). 판재 윤곽의 호도 같다(15차, 붙잡기 표의 호 요소).
 *   반경 보정 경로(공구 중심)의 호도 같다(19차, 워커가 보낸 보정 조각의 호 — 첫 점 식별자 nc-comp로 그 이동의 보정 조각).
 *   방향은 첫 점에서 원호를 따라 커서 쪽(잠금은 선이라 결과 방향에만 든다).
 *   첫 점이 놓인 원호는 코어 0.16.0이 찍은 점에 싣는 선분 식별자(measurePoints[0].segment·other)로 그 이동·윤곽에서 바로 찾고(18차),
 *   식별자가 없는 점(앱의 가운데 점·중심)이나 이동이 바뀌는 꼭짓점은 예전처럼 좌표로 찾는다(tangent.ts ArcTangents).
 *   코어는 원호를 나눈 현을 선분으로 보므로 첫 현의 끝을 가리키면 그 현 방향으로 잠그려 한다 — 커서 아래 점이 원호 위면 접선이 먼저다.
 *   커서 아래가 방향 추론(축·나란함·수직 발 — 툴팁이 그 이름)이면 코어 판정 그대로다. 잠글 것을 지금 못 보면(커서가 떠남) 코어처럼
 *   첫 점 뒤 마지막으로 본 방향 — 그것이 접선이었으면 접선. Shift는 앱 onKey가 코어보다 먼저 shiftDown을 불러 잠그고(코어는 잠금이 있으면
 *   Shift를 넘긴다) 떼면 shiftUp이 푼다(코어는 제가 잠근 Shift만 푼다). 툴팁·안내·결과는 "접선 방향"이라 적는다.
 *   116차: 코어 0.120.0은 제 Shift 잠금만 같은 누름의 Shift+Tab에서 되돌려, 앱이 건 접선 잠금은 이 모듈이 같은 꼴로 되돌린다(undoKey —
 *   Shift+Tab을 누르려고 먼저 누른 Shift면 잠금을 풀고 그 Tab을 코어 마우스 Tab 돌리기에 넘긴다. 받지 못하면 잠근 그대로).
 * 둘째 점을 찍거나 측정을 지우거나 측정을 끄면 코어가 잠금을 푼다.
 * - 코어 거리 글상자 비키기(코어 0.13.0 setMeasureLabelAvoid): 툴팁이 먼저 서려는 자리(placeTip의 첫 자리 — 점 오른쪽 아래, 코어 글상자와
 *   상관없이 정해진다)를 캔버스 기준으로 넘겨 코어 글상자가 먼저 비키게 하고, 그래도 겹치면 placeTip이 예전처럼 툴팁을 옮긴다(둘이 서로 쫓지 않는다).
 *   휴대폰 정밀 조준 중에는 십자선(커서 둘레 반지름)과 손가락 자리도 넘긴다(setAim — 십자선을 옮기는 같은 처리 안에서, 같은 프레임에).
 *   23차: 측정 중에는 3D 보기 위에 떠서 캔버스 덧그림을 가리는 것(코어 뷰 큐브, 측정 띠·해석 판단 띠·재생 띠 — host.overlays)의 자리도 넘긴다(coverRects).
 *   25차: 뷰 큐브 자리는 DOM에서 찾지 않고 코어 0.23.0 viewCubeRect로 읽는다.
 *   휴대폰은 거리 글상자가 화면 폭의 절반을 넘어 두 점이 오른쪽 위면 뷰 큐브 밑에, 아래면 측정 띠 밑에 그려졌다. 코어는 기본 자리가 넘긴 자리와
 *   겹칠 때만 옮기므로 겹치지 않는 측정의 글상자 자리는 그대로다. 측정을 끄거나 툴팁을 숨기고 조준도 하지 않으며 떠 있는 것도 없으면 null.
 *   33차(코어 0.31.0 points): 측정 중에는 두 측정 점 표식(첫 점·미리 보기 점 또는 두 점째)을 덮는 자리도 옮기게 늘 points: true를 넘긴다(넘길 영역이 없어도 —
 *   마우스에서도). 0.30.0까지 코어는 기본 자리(두 점 화면 가운데의 오른쪽 위)가 표식을 덮어도 그대로 그려, 휴대폰 정밀 조준 미리 보기에서 거리 글상자가
 *   첫 점 표식을 덮었다(글상자가 화면 폭의 절반을 넘어 캔버스 안으로 당겨지므로 더 자주). 표식을 덮지 않던 자리는 그대로다. 측정을 끄면 null.
 *   35차(코어 0.33.0 snapshotPoints): 같은 값에 snapshotPoints: true를 더해 그림 저장(PNG 단추 — toBlob)의 거리 글상자도 표식을 비킨다.
 *   34차까지 그림 저장은 측정 중이면(이 값을 늘 넘긴다) 덧그림을 기본 자리로 다시 그려, 화면에서 비킨 글상자가 그림에서는 표식을 덮었다. 그림에는 십자선·툴팁이 없어
 *   그것들은 보지 않고 표식만 비킨다(화면 글상자를 옮긴 것이 표식뿐이면 화면과 같은 자리).
 * - 24차: 측정 띠의 끌어온 점 단추(measure-track.ts)는 이 모듈의 띠 위 알림(showFlash)을 함께 쓰고, 끌어온 점 수가 바뀌면(머무르기로 기억함)
 *   host.changed로 알린다.
 */
import type { MeasureHoverSnap, MeasureLabelAvoid, MeasureLabelRect, Viewer3d } from 'opencad-viewer3d';
import { translate } from '../../site/i18n-core.mjs';
import { AIM_FINGER_PX, AIM_RETICLE_RADIUS } from './aim';
import { h, holdOpen, toast } from './dom';
import { icon } from './icons';
import { TANGENT_LABEL, TRACK_PARALLEL_LABEL, TRACK_PERPENDICULAR_LABEL, lockMeet, lockMeetLabel, snapLabel, trackMark } from './measure';
import type { FirstPoint } from './tangent';

// 216차: 잠금 글·잠근 방향 이름(LockName·LOCK_HINTS·SHIFT_LOCK_HINTS·ARROW_LOCK_HINT·NO_LOCK_TOUCH·NO_LOCK_MOUSE·lockName)은 이 조각만 써 measure.ts(첫 화면 조각)에서 옮겼다 — 시험은 이 모듈에서 가져온다

/**
 * 잠근 방향(코어 0.10.0 추론 잠금): 축 셋, 선분과 나란히, 첫 점에서 선분에 내린 수직,
 * 첫 점이 원호 끝일 때 그 원호의 접선(앱이 코어에 방향으로 주는 나란함 잠금 — tangent.ts·measure-lock.ts)
 */
export type LockName = 'x' | 'y' | 'z' | 'parallel' | 'perpendicular' | 'tangent';

/** 잠갔을 때 상태 줄·측정 띠에 적는 글 */
export const LOCK_HINTS: Record<LockName, string> = {
  x: 'X축 방향으로 잠금',
  y: 'Y축 방향으로 잠금',
  z: 'Z축 방향으로 잠금',
  parallel: '나란한 방향으로 잠금',
  perpendicular: '수직 방향으로 잠금',
  tangent: '접선 방향으로 잠금',
};

/** 잠그지 않았을 때(키보드 기기) 커서 아래에 Shift로 잠글 방향이 있으면(코어 0.12.0 measureHoverLock): 그 방향 */
export const SHIFT_LOCK_HINTS: Record<LockName, string> = {
  x: 'Shift로 X축 방향 잠그기',
  y: 'Shift로 Y축 방향 잠그기',
  z: 'Shift로 Z축 방향 잠그기',
  parallel: 'Shift로 나란한 방향 잠그기',
  perpendicular: 'Shift로 수직 방향 잠그기',
  tangent: 'Shift로 접선 방향 잠그기',
};

/** 잠그지 않았고 Shift로 잠글 방향도 없을 때(키보드 기기): 화살표(→ X · ← Y · ↑ Z, ↓ 지금 방향) */
export const ARROW_LOCK_HINT = '화살표로 방향 잠금';

/** 잠금 단추를 눌렀는데 잠글 방향이 없을 때(손가락 기기·마우스) */
export const NO_LOCK_TOUCH = '잠글 방향이 없습니다: 길게 눌러 조준하며 축·나란한 방향에 맞춘 뒤 누르세요';
export const NO_LOCK_MOUSE = '잠글 방향이 없습니다: 커서를 축·나란한 방향에 맞춘 뒤 누르세요';

/** 코어 잠금 상태(measureInferenceLock) → 잠근 방향 이름 */
export function lockName(l: { kind: string; axis?: 'x' | 'y' | 'z' } | null | undefined): LockName | null {
  if (!l) return null;
  if (l.kind === 'axis') return l.axis ?? null;
  return l.kind === 'parallel' ? 'parallel' : l.kind === 'perpendicular' ? 'perpendicular' : null;
}

type V3 = [number, number, number];

/** 이 모듈이 쓰는 뷰어 기능(시험에서 가짜로 바꿀 수 있게) */
export type LockViewer = Pick<
  Viewer3d,
  | 'canvas'
  | 'measureMode'
  | 'measurePointCount'
  | 'measurePoints'
  | 'measureHoverSnap'
  | 'measureHoverLock'
  | 'measureInferenceLock'
  | 'measureLabelRect'
  | 'measureTrackPoints'
  | 'setMeasureInferenceLock'
  | 'setMeasureLabelAvoid'
  | 'project'
  | 'viewCubeRect'
> &
  // 57차: 가상 커서(56차 keysnap.ts — 켜고 끄면 방향 잠금 안내가 바뀐다). 99차: 측정 미리 보기 바뀜 알림(코어 0.103.0 — attach).
  // 100차: 카메라 바뀜 알림(attach — 툴팁 자리만 다시 놓기). 116차: 키 넘기기(undoKey — Shift+Tab 되돌리기). 가짜 뷰어는 없어도 된다
  Partial<Pick<Viewer3d, 'keyboardCursor' | 'onMeasureHoverChange' | 'onCameraChange' | 'handleKey'>>;

export interface MeasureLockHost {
  viewer(): LockViewer | null;
  /** 손가락이 주인 기기인지(알림 글) */
  touch(): boolean;
  /** 툴팁을 붙일 층(3D 보기) */
  layer: HTMLElement;
  /**
   * 잠금·찍은 점 수·Shift로 잠글 방향·끌어온 점 수가 바뀌었다(상태 줄·측정 띠 다시 그리기 — 끌어온 점은 코어 머무르기가 타이머로 기억하고
   * 101차부터 코어 0.107.0이 그 그림 뒤 미리 보기 알림을 보내 그때 알아챈다. 정밀 조준 십자선을 멈춰 기억한 점도 측정 띠의 끌어온 점 버튼 수에 들어가게)
   */
  changed(): void;
  /**
   * 첫 측정 점(코어 measurePoints[0] — 0.16.0부터 그 점이 놓인 선분 식별자 segment·other)이 원호(G2/G3 이동·판재 윤곽 호)의
   * 시작·끝·가운데 점이나 그 밖의 원호 위 자리이고 커서 아래 점 p가 그 원호 위면 그 자리의 단위 접선(tangent.ts ArcTangents — 식별자가 있으면
   * 그 이동·윤곽만, 없으면 좌표로), 아니면 null. 원호를 모르는 문서·시험은 두지 않아도 된다
   */
  arcTangent?(first: FirstPoint, p: V3): V3 | null;
  /** 첫 점의 곡선을 찾은 길(자동 확인용 — ArcTangents.by) */
  tangentBy?(): string | null;
  /**
   * 3D 보기 위에 떠서 코어 거리 글상자를 가리는 앱 요소(측정 띠·해석 판단 띠·재생 띠). 숨었거나 크기가 0이면 뺀다.
   * 코어 뷰 큐브 자리는 코어가 알려 준다(viewCubeRect). 없으면 뷰 큐브만
   */
  overlays?(): readonly Element[];
}

type Box = { left: number; top: number; width: number; height: number };

/**
 * 캔버스 위에 떠 있는 요소 자리(화면 좌표 getBoundingClientRect)를 코어 거리 글상자가 비킬 캔버스 기준 사각형으로(23차).
 * 바깥쪽으로 정수에 맞추고(왼쪽·위는 내림, 오른쪽·아래는 올림 — 같은 자리면 같은 값이라 코어에 다시 주지 않는다) 캔버스 밖은 잘라 낸다.
 * 크기가 0인 것(숨긴 요소 — display: none)과 캔버스와 겹치지 않는 것은 뺀다
 */
export function coverRects(canvas: Box, boxes: readonly Box[]): MeasureLabelRect[] {
  const out: MeasureLabelRect[] = [];
  for (const b of boxes) {
    if (!(b.width > 0 && b.height > 0)) continue;
    const x0 = Math.max(0, Math.floor(b.left - canvas.left));
    const y0 = Math.max(0, Math.floor(b.top - canvas.top));
    const x1 = Math.min(Math.ceil(canvas.width), Math.ceil(b.left - canvas.left + b.width));
    const y1 = Math.min(Math.ceil(canvas.height), Math.ceil(b.top - canvas.top + b.height));
    if (x1 > x0 && y1 > y0) out.push({ x: x0, y: y0, width: x1 - x0, height: y1 - y0 });
  }
  return out;
}

/** 방향 추론 붙잡기(첫 점을 지나는 선 위의 점 — 툴팁이 그 이름): 원호 접선보다 코어 판정이 먼저 */
const INFERRED = new Set(['axis', 'parallel', 'perpendicular']);
/** 같은 방향(부호 무시)으로 볼 단위 벡터 내적 */
const SAME_DIR = 1 - 1e-9;
const sameLine = (a: readonly number[], b: readonly number[]): boolean => Math.abs(a[0]! * b[0]! + a[1]! * b[1]! + a[2]! * b[2]!) >= SAME_DIR;

/** 측정 띠 알림 종류: 잠글 방향이 없음(잠금이 걸리면 거둔다) */
const NO_LOCK = 'no-lock';

/** 116차: 같은 누름의 Shift+Tab 되돌리기를 버리는 포인터 이동(화면 화소 — 코어 DRAG_START_PX와 같다) */
const UNDO_PX = 4;

/**
 * 117차: 비운 띠 위 알림의 모습 — 화면에서는 1화소로 잘라 감추고 숨김 속성은 두지 않는다(keysnap.ts .key-live와 같은 값).
 * 알림 영역(role=status)은 글을 바꾸기 전에 접근성 트리에 있어야 화면 읽기 프로그램이 바뀐 글을 읽는다 — 숨김을 글과 함께 풀면 읽지 않을 수 있다
 */
const FLASH_EMPTY = 'position:absolute;width:1px;height:1px;margin:-1px;padding:0;border:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap';

/**
 * 잠금 안내(첫 점을 찍은 뒤 결과가 없을 때만 — 둘째 점의 방향을 잡는 동안): 잠갔으면 그 방향, 아니면 키보드 기기에만 —
 * 커서 아래에 Shift로 잠글 방향(hover — 코어 measureHoverLock)이 있으면 "Shift로 그 방향 잠그기", 없으면 화살표 안내
 * (손가락 기기는 측정 띠의 잠금 단추). 상태 줄·측정 띠는 안내 글 다음에 따로 둔다(번역이 안내 글을 한 덩어리로 찾게)
 * 57차: 3D 보기의 가상 커서가 켜진 동안(cursor — 56차 keysnap.ts)은 화살표가 커서를 옮기므로 화살표 안내를 내지 않는다(Shift로 잠글 방향이 있으면 그 안내).
 * 203차: 그 동안 축은 X·Y·Z로 잠그므로(MeasureLock axisKey) Shift로 잠글 방향이 없으면 그 안내(CURSOR_LOCK_HINT — 57차는 안내 없음, 205차: 지금 방향 L도).
 * 측정 도구가 있을 때만 쓰므로 이 조각에 둔다(56차까지 measure.ts — 첫 화면 JS를 줄이려고 옮김, 앱은 MeasureLock.hint로 묻는다)
 */
export function lockHint(points: number, hasResult: boolean, lock: LockName | null, touch = false, hover: LockName | null = null, cursor = false): string | null {
  if (hasResult || points !== 1) return null;
  if (lock) return LOCK_HINTS[lock];
  if (touch) return null;
  return hover ? SHIFT_LOCK_HINTS[hover] : cursor ? CURSOR_LOCK_HINT : ARROW_LOCK_HINT;
}

/**
 * 203차: 가상 커서가 켜진 동안의 축 잠금 안내(화살표 안내 ARROW_LOCK_HINT 꼴 — 측정 조각 글이라 첫 화면 measure.ts가 아닌 이 조각에).
 * 205차: 204차 L(지금 방향)도 적는다 — 3D 보기 설명(keysnap.ts KEY_HELP 「X·Y·Z로 축 방향을, L로 지금 방향을 잠급니다」)의 낱말(잠금 글자 lockKeyOf를 모두 — tests/app/shortcuts.test.ts)
 */
export const CURSOR_LOCK_HINT = 'X·Y·Z로 축 방향, L로 지금 방향 잠금';

/** 203차: 가상 커서가 켜진 동안 X·Y·Z로 잠금을 풀었을 때 가상 커서 알림 영역에 넣는 글(잠근 때는 잠금 안내 LOCK_HINTS 그대로) */
export const UNLOCK_SAID = '방향 잠금을 풀었습니다';

/**
 * 203차: 가상 커서가 켜진 동안 축을 잠그는 키 → 축(X·Y·Z가 아니면 null — 204차 L은 lockKeyOf). 적힌 글자(key — 대소문자 무시, 독일어 자판의 Y·Z 자리도 적힌 대로)가 먼저이고,
 * 라틴 글자가 아니면(한글 입력기의 ㅌ·ㅛ·ㅋ, 입력기 처리 중 'Process') 물리 키(code KeyX·KeyY·KeyZ — 코어 걷기 키와 같은 까닭, 다만 축 이름이라 적힌 글자가 먼저)
 */
export function axisKeyOf(e: { key: string; code?: string }): 'x' | 'y' | 'z' | null {
  const c = lockKeyOf(e);
  return c === 'l' ? null : c;
}

/**
 * 204차: 가상 커서가 켜진 동안 측정 방향을 잠그는 키 → X·Y·Z(그 축)·L(지금 방향 — 커서가 꺼졌을 때의 ↓), 아니면 null.
 * 글자 읽기는 203차 axisKeyOf와 같다(적힌 글자 먼저, 라틴 글자가 아니면 물리 키 — 한글 입력기 L 자리의 ㅣ는 code KeyL)
 */
export function lockKeyOf(e: { key: string; code?: string }): 'x' | 'y' | 'z' | 'l' | null {
  const k = e.key.length === 1 ? e.key.toLowerCase() : '';
  const c = /^[a-z]$/.test(k) ? k : /^Key[XYZL]$/.test(e.code ?? '') ? e.code![3]!.toLowerCase() : '';
  return c === 'x' || c === 'y' || c === 'z' || c === 'l' ? c : null;
}

/** 57차: 3D 보기의 가상 커서가 켜져 있는지(코어 keyboardCursor — 가짜 뷰어는 값이 없거나 객체가 아닐 수 있다) */
const cursorOn = (v: LockViewer): boolean => typeof v.keyboardCursor === 'object' && v.keyboardCursor !== null;
/** 툴팁과 점 사이(가로·세로), 3D 보기 가장자리 여백 */
const TIP_GAP = 12;
const TIP_EDGE = 4;

/**
 * 툴팁 글(붙잡은 종류 이름, 잠갔는지). 붙잡지 않은 점·미리 보기가 없으면 null. 다른 점에서 끌어온 축(코어 0.16.0 — trackFrom이 있고
 * 첫 점에서 그 축 방향이 아님)은 '끌어온 점에서 X축', 첫 점 축 위에서 끌어온 점과 나란한 자리(방향이 있음)는 'X축 방향' 그대로.
 * 0.17.0: 끌어온 축이 선분과 만나는 점(segment)은 '끌어온 점에서 X축 · 모서리 위', 끌어온 축끼리의 교차(trackOther)는 '끌어온 X축과 Y축의 교차'.
 * 0.18.0: 축이 면을 뚫는 점(face)은 '끌어온 점에서 X축 · 면 위'·'X축 · 면 위', 첫 점 축이 선분과 만나는 점(trackFrom 없이 segment)은 'X축 · 모서리 위'.
 * 0.19.0: 잠근 선이 선분과 만나는 점·면을 뚫는 점(locked에 segment·face)은 '잠근 X축 · 모서리 위'·'잠근 나란한 방향 · 면 위'.
 * 0.21.0: 잠근 선이 끌어온 점의 축과 만나는 점(locked에 trackOther)은 '잠근 X축 · 끌어온 점에서 Y축', 잠근 축 위 끌어온 점과 나란한 자리(locked에 trackFrom만)는
 * '잠근 Z축 · 끌어온 점과 나란히'(이름에 잠금이 들어 있어 "잠금"을 다시 붙이지 않는다).
 * 31차(코어 0.29.0 trackDirs { meets }): 끌어온 점에서 모서리와 나란한 선·수직인 선이 다른 것과 만나는 점은 '끌어온 점에서 모서리와 나란히 · X축 위'처럼(trackDirName).
 * 32차(코어 0.30.0 meets { guides }): 다른 끌어온 점의 나란한 선·수직인 선과 만나는 점은 '끌어온 점에서 모서리에 수직 · 끌어온 점 나란한 선 위'처럼
 * 109차(코어 0.115.0 perpendicularDirs): 첫 점에서 지나간 모서리에 수직인 방향 위 점(perpendicularDir)은 '모서리에 수직'(수직 발 '수직점'과 가른다 — perpDirName)
 */
export function snapTip(hv: TrackDirPoint | null | undefined): { name: string; locked: boolean } | null {
  if (!hv?.snap) return null;
  return { name: perpDirName(hv) ?? trackDirName(hv) ?? snapLabel(hv.snap, hv.axis, trackMark(hv)), locked: !!hv.locked };
}

/**
 * 112차(코어 0.118.0 MeasureHoverSnap.cycle — setMeasureSnap tabCycle로 마우스 미리 보기 자리 후보를 Tab·Shift+Tab으로 돌린 동안만 있다): 툴팁 이름 뒤에 붙이는 차례·수
 * (「끝점 2/4」의 ' 2/4'). 가상 커서 알림의 차례 글(코어 틀 열쇠 'order' — '{0} {1}/{2}')에서 이름 {0} 뒤 글과 같다. 그 틀은 한글이 없어 keysnap.ts keySnapMessageFn이
 * 다섯 언어 모두 코어 기본 틀로 두므로 사전 항목이 없다(tests/app/measure-lock.test.ts가 코어 keySnapText로 견준다 — 코어 틀 값을 가져오면 이 조각이 코어 keysnap 모듈과 묶인다).
 * 툴팁에서는 이름과 다른 마디라 화면 번역층은 이름만 옮긴다(수는 한글이 없어 그대로). 돌리지 않으면 빈 글
 */
export const cycleOrder = (c: MeasureHoverSnap['cycle']): string => (c ? ` ${c.index + 1}/${c.count}` : '');

/** 줄 바꿈 없는 빈칸(U+00A0 — 같은 알림 글을 다시 읽게 붙인다, keysnap.ts say와 같다) */
const NBSP = String.fromCharCode(0xa0);

/** 붙잡은 점(미리 보기 measureHoverSnap·찍은 점 measurePoints)에서 이름을 가르는 값 */
type TrackDirPoint = Pick<MeasureHoverSnap, 'snap' | 'axis' | 'locked' | 'trackFrom' | 'trackOther' | 'segment' | 'face' | 'direction' | 'trackGuide' | 'perpendicularDir'>;

/**
 * 첫 점에서 지나간 모서리에 수직인 방향 위의 점 이름(109차 — 코어 0.115.0 inference.perpendicularDirs, 툴팁·측정 결과). 코어 종류는 수직 발과 같은 'perpendicular'이라
 * perpendicularDir로 가른다. 말은 끌어온 점의 「끌어온 점에서 모서리에 수직」(TRACK_PERPENDICULAR_LABEL)에서 끌어온 점을 뺀 것(첫 점의 「나란한 방향」에도 첫 점이라는 말이 없다)이고
 * SketchUp 「모서리에 수직」 추론과 같다. 측정 도구가 있을 때만 쓰므로 이 조각에 둔다(첫 화면 measure.ts snapLabel은 그대로 — 결과에는 trackDirNames가 이름을 붙인다)
 */
export const PERPENDICULAR_DIR_LABEL = '모서리에 수직';

/** 수직 방향 위 점이면 그 이름(잠그지 않은 값에만 perpendicularDir이 실린다 — 잠근 뒤는 수직 발 잠금과 같은 값), 아니면 null */
const perpDirName = (p: TrackDirPoint | null | undefined): string | null => (p?.perpendicularDir && p.snap === 'perpendicular' ? PERPENDICULAR_DIR_LABEL : null);

/**
 * 끌어온 점에서 모서리와 나란한 선·수직인 선이 만난 것(31차 — 코어 0.29.0 trackDirs { meets }, 코어 README의 가르는 법): 첫 점 축이면 그 축('x'·'y'·'z' — axis·direction),
 * 다른 끌어온 점의 축이면 't' + 축(trackOther), 선분·윤곽선이면 'edge'(segment), 그물 면이면 'face', 첫 점의 나란함이면 'par'(axis 없이 direction — 그 선 위 점에는 direction이 없다).
 * 32차(코어 0.30.0 meets { guides }): 다른 끌어온 점의 나란한 선이면 'gpar', 수직인 선이면 'gperp'(trackGuide — 그 점의 안내 종류).
 * 끌어온 점 안내가 아니거나(trackMark가 'dir'이 아님) 만난 것이 없으면(그 선 위 점) null
 */
export type TrackDirMeet = 'x' | 'y' | 'z' | 'tx' | 'ty' | 'tz' | 'edge' | 'face' | 'par' | 'gpar' | 'gperp';
export function trackDirMeet(p: TrackDirPoint | null | undefined): TrackDirMeet | null {
  if (!p || trackMark(p) !== 'dir') return null;
  if (p.trackGuide) return p.trackGuide.kind === 'parallel' ? 'gpar' : 'gperp';
  return p.axis ?? (p.trackOther ? (`t${p.trackOther.axis}` as const) : p.segment ? 'edge' : p.face ? 'face' : p.direction ? 'par' : null);
}

/** 만난 것의 이름(trackDirName의 ' · ' 뒤, '위' 앞) */
const MEET_AT: Record<TrackDirMeet, string> = {
  x: 'X축',
  y: 'Y축',
  z: 'Z축',
  tx: '끌어온 점 X축',
  ty: '끌어온 점 Y축',
  tz: '끌어온 점 Z축',
  edge: '모서리',
  face: '면',
  par: '나란한 방향',
  gpar: '끌어온 점 나란한 선',
  gperp: '끌어온 점 수직인 선',
};

/**
 * 만나는 점의 이름(툴팁·측정 결과, 31차): 끌어온 점 안내 이름(TRACK_PARALLEL_LABEL·TRACK_PERPENDICULAR_LABEL) 뒤에 만난 것 —
 * '… · X축 위'(첫 점 축), '… · 나란한 방향 위'(첫 점의 나란함), '… · 끌어온 점 Y축 위'(다른 끌어온 점의 축), '… · 모서리 위', '… · 면 위'(사전에 18개).
 * 32차: 두 끌어온 점의 안내 선끼리 만나는 점은 '… · 끌어온 점 나란한 선 위'·'… · 끌어온 점 수직인 선 위'(나란한 두 선은 만나지 않아
 * '끌어온 점에서 모서리와 나란히 · 끌어온 점 나란한 선 위'는 없다 — 사전에 3개).
 * 만나는 점이 아니면 null(30차 이름 그대로)
 */
export function trackDirName(p: TrackDirPoint | null | undefined): string | null {
  const m = trackDirMeet(p);
  if (!m) return null;
  return `${p!.snap === 'parallel' ? TRACK_PARALLEL_LABEL : TRACK_PERPENDICULAR_LABEL} · ${MEET_AT[m]} 위`;
}

/**
 * 측정 결과 두 점의 만나는 점 이름(31차 — app.ts onMeasure가 찍은 점 measurePoints로 붙이고 첫 화면 snapPair가 그 이름을 그대로 쓴다.
 * 코어 결과 MeasureResult에는 만난 것이 없다). 만나는 점이 아닌 점은 빼고, 둘 다 아니면 빈 객체.
 * 109차: 첫 점에서 지나간 모서리에 수직인 방향 위에 찍은 점도 '모서리에 수직'(코어 결과는 수직 발과 같은 snapB 'perpendicular' — 찍은 점의 perpendicularDir로 가른다)
 */
export function trackDirNames(points: readonly (TrackDirPoint | null | undefined)[]): { nameA?: string; nameB?: string } {
  const a = perpDirName(points[0]) ?? trackDirName(points[0]);
  const b = perpDirName(points[1]) ?? trackDirName(points[1]);
  return { ...(a ? { nameA: a } : {}), ...(b ? { nameB: b } : {}) };
}

/**
 * 툴팁 왼쪽 위 자리(층 기준 CSS 화소): 점(px, py) 오른쪽 아래가 먼저이고, 층(width × height) 밖으로 나가거나 피할 상자(코어 거리 글상자 —
 * 같은 층 기준)와 겹치면 왼쪽 아래·오른쪽 위·왼쪽 위 차례로 본다. 층 안이면서 겹치지 않는 곳이 없으면 층 안인 첫 자리.
 * 31차: 넷 모두 층 밖이면(점 양옆 어느 쪽에도 들어가지 않는 넓은 툴팁 — 휴대폰 폭의 긴 이름) 점 아래·위에서 가로만 층 안으로 민 자리(겹치지 않는 것 먼저),
 * 그것도 층 밖이면 오른쪽 아래.
 * 191차: covers(뷰 큐브·측정 띠·해석 판단 띠 — 같은 층 기준, coverRects로 잰 것)도 비킨다 — 같은 차례에서 글상자와 겹치지 않는 자리가 먼저이고,
 * 그다음 covers와 겹친 넓이가 가장 작은 자리(같으면 앞 차례 — 다 겹쳐도 숨기지 않는다). covers가 없으면 전과 같다
 */
export function placeTip(px: number, py: number, w: number, ht: number, layer: { width: number; height: number }, avoid: MeasureLabelRect | null, covers: readonly MeasureLabelRect[] = []): { x: number; y: number } {
  const right = px + TIP_GAP;
  const left = px - TIP_GAP - w;
  const below = py + TIP_GAP;
  const above = py - TIP_GAP - ht;
  const spots = [
    { x: right, y: below },
    { x: left, y: below },
    { x: right, y: above },
    { x: left, y: above },
  ];
  const inside = (s: { x: number; y: number }): boolean => s.x >= TIP_EDGE && s.y >= TIP_EDGE && s.x + w <= layer.width - TIP_EDGE && s.y + ht <= layer.height - TIP_EDGE;
  const clear = (s: { x: number; y: number }): boolean => !avoid || s.x >= avoid.x + avoid.width || avoid.x >= s.x + w || s.y >= avoid.y + avoid.height || avoid.y >= s.y + ht;
  const x = Math.max(TIP_EDGE, Math.min(right, layer.width - TIP_EDGE - w));
  const slid = [
    { x, y: below },
    { x, y: above },
  ];
  // 글상자와 겹치면 어느 넓이 합(툴팁 넓이 × covers 수 이하)보다 큰 값을 더해 겹치지 않는 자리가 늘 먼저다
  const big = w * ht * covers.length + 1;
  const cost = (s: { x: number; y: number }): number =>
    (clear(s) ? 0 : big) + covers.reduce((a, r) => a + Math.max(0, Math.min(s.x + w, r.x + r.width) - Math.max(s.x, r.x)) * Math.max(0, Math.min(s.y + ht, r.y + r.height) - Math.max(s.y, r.y)), 0);
  const pick = (list: { x: number; y: number }[]): { x: number; y: number } | undefined =>
    list.filter(inside).reduce<{ x: number; y: number } | undefined>((b, s) => (!b || cost(s) < cost(b) ? s : b), undefined);
  return pick(spots) ?? pick(slid) ?? spots[0]!;
}

export class MeasureLock {
  /** 측정 띠의 잠금 단추 */
  readonly button: HTMLButtonElement;
  /** 측정 띠 위 알림 */
  readonly flash: HTMLDivElement;
  private readonly tip: HTMLDivElement;
  private raf = 0;
  /** schedule을 부른 횟수(기다리는 동안 또 불렸는지) */
  private want = 0;
  private flashKind: string | null = null;
  /** 134차: 띠 위 알림에 마지막으로 넣은 원문(같은 글을 잇달아 띄우면 NBSP를 번갈아 붙인다 — showFlash) */
  private flashSaid = '';
  private lastKey = '';
  /** 앱이 원호 접선으로 잠근 방향(코어 잠금이 이것과 같은 방향의 'api' 잠금이면 접선 잠금) */
  private tangent: V3 | null = null;
  /** 접선 잠금을 Shift로 걸었는지(떼면 푼다) */
  private shiftTangent = false;
  /** 첫 점 뒤 마지막으로 본 잠글 것이 원호 접선이었으면 그 방향(코어 방향을 보면 지운다 — 코어의 "마지막으로 본 방향"과 같은 차례) */
  private seenTangent: V3 | null = null;
  /** seenTangent·접선 결과를 맞춘 첫 점(바뀌면 잊는다) */
  private firstKey = '';
  /** 접선 잠금으로 찍은 둘째 점을 결과에서 알아보려고 남기는 방향(다른 잠금·첫 점이 바뀌면 지운다) */
  private resultTangent: V3 | null = null;
  /** 코어 글상자가 비킬 툴팁 첫 자리(캔버스 기준, 툴팁을 숨겼으면 null) */
  private tipAvoid: MeasureLabelRect | null = null;
  /** 코어 글상자가 비킬 손가락 자리(캔버스 기준, 정밀 조준 중이 아니면 null) */
  private aimAvoid: MeasureLabelRect | null = null;
  /** 코어 글상자가 비킬 떠 있는 것(뷰 큐브·띠 — 캔버스 기준, 측정 중일 때만) */
  private coverAvoid: MeasureLabelRect[] = [];
  /** 측정 중인지(update가 맞추고 reset이 끈다 — 측정 중이면 코어 글상자가 측정 점 표식도 비키게 한다, 33차) */
  private measuring = false;
  /** 코어에 마지막으로 준 비킬 자리(같으면 다시 주지 않는다) */
  private avoidKey = 'null';
  /** 툴팁을 붙인 점(캔버스 기준 화면 좌표 — 크기가 바뀌면 다시 놓는다) */
  private tipAt: { x: number; y: number } | null = null;
  /**
   * 100차: 툴팁을 붙인 점의 세계 좌표(update가 툴팁을 보일 때 미리 보기 점으로 정하고, 툴팁 글이 없으면 null). 카메라만 바뀌면 이것을 다시 투영한다(follow).
   * 카메라로 화면 밖에 나가 숨긴 동안도 남겨 두어 다시 들어오면 같은 글로 보인다
   */
  private tipPoint: readonly number[] | null = null;
  /** 112차: 마지막으로 맞춘 돌리기 글(이름 + 차례·수 — 칸이 없으면 빈 글. 같은 값으로 다시 맞출 때 또 알리지 않는다) */
  private cycleSaid = '';
  /** 203차: X·Y·Z 잠금 알림을 건 차례(sayLock — 한 프레임 안에 여러 번 누르면 마지막 것만 알린다) */
  private lockSays = 0;
  /** 158차: update가 맞춘 툴팁의 글·점(이름 + 차례·수, 잠금, 점 좌표 — 툴팁 글이 없으면 빈 글) */
  private tipSaid = '';
  /** 158차: Esc로 거둔 툴팁의 tipSaid(escTip — 거두지 않았으면 빈 글). 같은 값인 동안 다시 띄우지 않는다 */
  private tipOff = '';
  /**
   * 116차: 이 Shift 누름이 건 원호 접선 잠금과 걸기 전 상태 — 같은 누름의 첫 Shift+Tab이 되돌린다(undoKey — 코어 0.120.0이 제 Shift 잠금에 하는 것과 같은 꼴).
   * t = 건 접선, x·y = 누를 때 포인터(화면 좌표), tangent·result = 걸기 전 접선 기록. 다른 키(누름·뗌)·누르기·3D 보기 떠남·4화소 넘는 이동·Shift 뗌이면 버린다(잠근 채)
   */
  private undo: { t: V3; x: number; y: number; tangent: V3 | null; result: V3 | null } | null = null;
  /** 116차: 이 Shift 누름을 되돌리기에 썼다 — 뗄 때까지 같은 누름(다른 Shift 키)으로 다시 잠그지 않는다(SKP 126차 shiftUsed와 같다) */
  private shiftUsed = false;
  /** 116차: 3D 보기 위 마지막 마우스·펜 포인터 자리(화면 좌표 — 손가락·떠남이면 null) */
  private ptr: { x: number; y: number } | null = null;

  constructor(private readonly host: MeasureLockHost) {
    this.tip = h('div', { class: 'snap-tip', 'aria-hidden': 'true', hidden: true });
    host.layer.append(this.tip);
    // 번역층이 툴팁 글을 바꿔 크기가 달라지면 다시 놓는다(같은 프레임 — 그리기 전에 온다). 크기를 알리지 않는 환경(jsdom)은 update의 자리 그대로
    if (typeof ResizeObserver === 'function')
      new ResizeObserver(() => {
        const v = this.host.viewer();
        if (this.tip.hidden || !v) return;
        this.placeTipNow(v);
        this.pushAvoid();
      }).observe(this.tip);
    this.button = h('button', { class: 'mb-btn icon mb-lock', type: 'button', title: '지금 방향 잠그기(다시 누르면 풀기)', 'aria-label': '방향 잠금', 'aria-pressed': 'false', hidden: true, html: icon('lock') });
    let pressedAt = -Infinity;
    this.button.addEventListener('pointerdown', (e) => {
      if (e.pointerType === 'mouse') return;
      e.preventDefault();
      pressedAt = performance.now();
      this.toggle();
    });
    this.button.addEventListener('click', () => {
      if (performance.now() - pressedAt < 1000) return;
      this.toggle();
    });
    // 117차: 띠 안에 늘 두고 비었을 때는 화면에서만 감춘다(FLASH_EMPTY — 띠가 보이는 동안 알림 영역이 먼저 있게)
    this.flash = h('div', { class: 'measure-flash', role: 'status', style: FLASH_EMPTY });
  }

  /**
   * 뷰어가 생긴 뒤 한 번: 코어 측정 미리 보기 바뀜 알림과 카메라 바뀜 알림을 듣는다.
   * 99차(코어 0.103.0 onMeasureHoverChange): 미리 보기 값(measureHoverSnap·measureHoverLock)이 바뀐 그림을 다 그린 뒤 한 번 — 포인터 이동도, 코어가 포인터 밖에서
   * 다시 구하거나(깎기 재생의 메시 바꾸기·재생 붙잡기 한도·보이기·되감기 등) 버린 것도(캔버스를 떠남·끌기 시작·측정 점 찍기 포함). 그 그림의 값·거리 글상자 자리라
   * 기다리지 않고 맞춘다. 측정 중이 아니면 바로 돌아간다(측정을 끌 때 오는 null은 reset이 이미 거뒀다 — 측정을 끈 재생은 미리 보기가 없어 알림도 없다).
   * 101차(코어 0.107.0): 끌어온 점 목록(measureTrackPoints — 머무르기 끝·두 점째·측정 지우기 등)이 바뀐 그림 뒤에도 오므로(받는 값은 앞과 같을 수 있다 — update가
   * 목록 길이를 읽는다) 99차가 남긴 포인터 길(pointermove·pointerleave·pointerup → 두 프레임 뒤 update)을 걷었다. 그 길이 맞추던 나머지는 다른 길이 맞춘다:
   * 손가락 탭으로 찍은 첫 점(미리 보기가 없어 알림도 없다)은 app.ts의 떼기 듣기(측정 띠 맞추기 → update — 코어 캔버스 듣기 다음이라 찍은 점 수가 이미 바뀜),
   * 둘째 점은 코어 onMeasure(app.ts → schedule), Shift는 창 키 듣기(app.ts → schedule), 가상 커서 끄기는 키보드 붙잡기 알림(keysnap.ts → keyMeasured).
   * 미리 보기가 그대로인 포인터 이동(빈 곳·같은 스냅)과 측정을 끈 포인터 이동에는 이 모듈이 하는 일이 없다.
   * 100차(코어 onCameraChange — 카메라가 바뀐 그림 끝, 같은 그림의 onMeasureHoverChange보다 먼저): 휠·보기 키 F·1~7·카메라 움직임(뷰 큐브·전체 보기 —
   * 움직이는 동안 프레임마다)·3D 보기 크기로 카메라만 바뀌면 움직이는 동안은 미리 보기 값이 그대로라 위 알림이 없고, 멈춘 뒤 다시 구한 값이 바뀌면 한 번 온다(코어 0.110.0 —
   * 104차. 앱 API 카메라 함수 setCamera·setView·fit·zoomToRect 뒤에는 다시 구하지 않아 오지 않는다). 툴팁이 있을 때만(tipPoint — 측정을 끄면 reset이 지운다)
   * 그 점을 다시 투영해 자리만 옮긴다(follow — 글·잠금 상태는 그대로, 투영 하나와 DOM 자리 놓기). 툴팁이 없거나 측정 중이 아니면 바로 돌아간다
   */
  attach(v: LockViewer): void {
    v.onMeasureHoverChange?.(() => {
      if (v.measureMode) this.update();
    });
    v.onCameraChange?.(() => {
      if (this.tipPoint && v.measureMode) this.follow(v, this.tipPoint);
    });
    // 116차: 같은 누름의 Shift+Tab 되돌리기(undo)를 버리는 포인터·키. 창 키는 app.ts onKey(→ shiftDown)보다 뒤에 등록해 같은 창 capture에서
    // 그 다음·캔버스의 코어 키 듣기 앞에 온다(undoKey가 Tab을 코어보다 먼저 본다). 158차: 같은 자리에서 3D 보기 Esc로 툴팁을 거둔다(escTip)
    const c = v.canvas;
    c.addEventListener('pointermove', (e) => {
      this.ptr = e.pointerType === 'touch' ? null : { x: e.clientX, y: e.clientY };
      const u = this.undo;
      if (u && (!this.ptr || Math.hypot(e.clientX - u.x, e.clientY - u.y) >= UNDO_PX)) this.undo = null;
    });
    c.addEventListener('pointerdown', () => (this.undo = null));
    c.addEventListener('pointerleave', () => (this.ptr = this.undo = null));
    window.addEventListener(
      'keydown',
      (e) => {
        this.escTip(e);
        this.undoKey(e);
        this.axisKey(e);
      },
      true,
    );
    window.addEventListener(
      'keyup',
      (e) => {
        if (e.key !== 'Shift') this.undo = null;
      },
      true,
    );
  }

  /** 지금 잠근 방향(원호 접선으로 잠갔으면 'tangent') */
  get lock(): LockName | null {
    const l = this.host.viewer()?.measureInferenceLock;
    if (l && this.tangentLocked(l)) return 'tangent';
    return lockName(l);
  }

  /** 상태 줄·측정 띠의 방향 잠금 안내(측정 중일 때 — lockHint, 가상 커서가 켜졌는지는 뷰어에서). hasResult = 측정 결과가 있는지, touch = 손가락 기기 */
  hint(hasResult: boolean, touch: boolean): string | null {
    const v = this.host.viewer();
    return v?.measureMode ? lockHint(v.measurePointCount, hasResult, this.lock, touch, this.hoverLock, cursorOn(v)) : null;
  }

  /** 잠그지 않았을 때 Shift(·잠금 단추)가 지금 잠글 방향(원호 접선, 아니면 코어 measureHoverLock). 방향을 잡는 중이 아니면 null */
  get hoverLock(): LockName | null {
    const v = this.host.viewer();
    if (!v || !this.directing || v.measureInferenceLock) return null;
    if (this.tangentNow()) return 'tangent';
    return lockName(v.measureHoverLock);
  }

  /**
   * 커서 아래에서 잠글 원호 접선: 방향을 잡는 중이고 잠그지 않았으며, 커서 아래 점이 방향 추론(축·나란함·수직 발)이 아니고
   * 첫 점에 닿는 원호 위에 있으면 그 끝의 접선(host.arcTangent). 아니면 null
   */
  tangentNow(): V3 | null {
    const v = this.host.viewer();
    const at = this.host.arcTangent;
    if (!v || !at || !this.directing || v.measureInferenceLock) return null;
    const hv = v.measureHoverSnap;
    if (!hv || (hv.snap && INFERRED.has(hv.snap))) return null;
    const first = v.measurePoints[0];
    return first ? at.call(this.host, first, hv.point) : null;
  }

  /** 코어 잠금이 앱이 건 원호 접선 잠금인지(같은 방향의 'api' 나란함 잠금) */
  private tangentLocked(l: { kind: string; direction: readonly number[]; source?: string }): boolean {
    return !!this.tangent && l.kind === 'parallel' && l.source === 'api' && sameLine(l.direction, this.tangent);
  }

  /** 측정 결과의 둘째 점을 원호 접선 잠금으로 찍었는지(코어 결과는 나란함 — 이름만 접선 방향으로) */
  tangentResult(m: { lockedB?: boolean; snapB?: string | null; directionB?: readonly number[] } | null | undefined): boolean {
    return !!m?.lockedB && m.snapB === 'parallel' && !!m.directionB && !!this.resultTangent && sameLine(m.directionB, this.resultTangent);
  }

  /** 둘째 점의 방향을 잡는 중인지(첫 점을 찍었고 결과가 없음) */
  get directing(): boolean {
    const v = this.host.viewer();
    return !!v && v.measureMode && v.measurePointCount === 1;
  }

  /**
   * 다음 프레임(코어가 미리 보기를 구한 뒤)에 툴팁·잠금 상태를 맞춘다. 포인터 이동은 프레임에 맞춰 rAF 앞에 오므로 기다리는 동안 또 불리면
   * 그 이동의 미리 보기는 아직이다 — 맞춘 뒤 한 번 더 돈다(마지막 이동을 놓치지 않게)
   */
  schedule(): void {
    this.want++;
    if (this.raf) return;
    const w = this.want;
    this.raf = requestAnimationFrame(() => {
      this.raf = requestAnimationFrame(() => {
        this.raf = 0;
        this.update();
        if (this.want !== w) this.schedule();
      });
    });
  }

  /** 툴팁·잠금 단추·알림을 지금 상태로(잠금·찍은 점 수·Shift로 잠글 방향이 바뀌었으면 앱에 알린다) */
  update(): void {
    const v = this.host.viewer();
    const on = !!v && v.measureMode;
    this.track();
    const hv = on ? v!.measureHoverSnap : null;
    const snap = on ? snapTip(hv) : null;
    // 잠근 선이 모서리·면과 만나는 점(0.19.0)은 이름이 '잠근 X축 · 모서리 위'라 "잠금"을 다시 붙이지 않는다
    const meet = trackMark(hv);
    // 원호 접선으로 잠근 선 위의 점은 코어 종류(나란함) 대신 접선 방향(모서리·면과 만나면 '잠근 접선 방향 · 모서리 위')
    const tan = !!snap && snap.locked && hv?.snap === 'parallel' && !!v!.measureInferenceLock && this.tangentLocked(v!.measureInferenceLock);
    const tip = tan ? { ...snap!, name: lockMeet(meet) ? lockMeetLabel(TANGENT_LABEL, meet) : TANGENT_LABEL } : snap;
    const sp = tip && hv ? v!.project(hv.point) : null;
    // 112차: Tab으로 돌린 동안만 이름 뒤 차례·수(칸이 없으면 빈 글 — 툴팁 마디는 전과 같다)
    const order = tip ? cycleOrder(hv?.cycle) : '';
    this.sayCycle(order ? tip!.name : null, order);
    // 191차: 떠 있는 것(뷰 큐브·띠) 자리를 툴팁을 놓기 전에 잰다 — 툴팁도 비킨다(placeTipNow)
    this.coverAvoid = on ? this.covers(v!) : [];
    // 158차: Esc로 거둔 툴팁(escTip)은 같은 글·같은 점인 동안 다시 띄우지 않는다 — 점·이름·차례·잠금이 바뀌거나 미리 보기가 없어지면 풀린다
    this.tipSaid = tip ? `${tip.name}${order}|${tip.locked}|${hv!.point.join(',')}` : '';
    if (this.tipOff !== this.tipSaid) this.tipOff = '';
    if (!tip || !sp || !sp.onScreen || this.tipOff) {
      this.tip.hidden = true;
      this.tipAvoid = null;
      this.tipPoint = null;
    } else {
      this.tip.replaceChildren(h('span', {}, tip.name), ...(order ? [order] : []), ...(tip.locked && !lockMeet(meet) ? [' · ', h('b', { class: 'st-lock' }, '잠금')] : []));
      this.tip.classList.toggle('locked', tip.locked);
      this.tip.hidden = false;
      this.tipAt = { x: sp.x, y: sp.y };
      this.tipPoint = hv!.point;
      this.placeTipNow(v!);
    }
    this.measuring = on;
    this.pushAvoid();
    const lock = this.lock;
    if (lock) this.dropFlash(NO_LOCK);
    const directing = this.directing;
    this.button.hidden = !directing;
    this.button.setAttribute('aria-pressed', String(!!lock));
    this.button.classList.toggle('on', !!lock);
    this.button.title = lock ? '방향 잠금 풀기' : '지금 방향 잠그기(다시 누르면 풀기)';
    // 57차: 가상 커서를 켜고 끄면 방향 잠금 안내가 바뀐다(켜진 동안 화살표 안내 없음 — lockHint)
    const key = `${on ? v!.measurePointCount : -1}|${lock ?? ''}|${this.hoverLock ?? ''}|${on ? v!.measureTrackPoints.length : 0}|${on && cursorOn(v!) ? 1 : 0}`;
    if (key !== this.lastKey) {
      this.lastKey = key;
      this.host.changed();
    }
  }

  /**
   * 112차: 마우스 미리 보기 Tab 돌리기의 화면 읽기 알림(코어 0.118.0 남은 한계 — 코어는 가상 커서에만 알린다). 차례·수 칸이 있을 때만, 이름·차례가 바뀐 때 한 번
   * 같은 3D 보기 층의 가상 커서 알림 영역(keysnap.ts KeySnap.live — 번역층이 건너뛰어 지금 언어 글을 넣는다)에 툴팁과 같은 글을 지금 언어로 넣는다.
   * 칸은 Tab·Shift+Tab을 받은 때 생기고 포인터가 벗어나거나 Esc·찍기에 없어지므로 마우스만 쓰면 알리지 않고, 가상 커서가 켜진 동안은 칸이 없어 그 알림과 겹치지 않는다.
   * 영역은 3D 보기 조각을 받았을 때만 있다(없으면 알리지 않는다 — 앱이 넘기지 않고 층에서 찾아 첫 화면 조각을 그대로 둔다). 같은 글이 이어지면 끝에 NBSP를 붙여 다시 읽게
   */
  private sayCycle(name: string | null, order: string): void {
    const said = name === null ? '' : name + order;
    if (said === this.cycleSaid) return;
    this.cycleSaid = said;
    const live = said ? this.host.layer.querySelector<HTMLElement>('.key-live') : null;
    if (!live) return;
    const text = translate(name!, document.documentElement.lang || 'ko') + order;
    live.textContent = live.textContent === text ? text + NBSP : text;
  }

  /**
   * 툴팁 크기를 재어 점(tipAt — 캔버스 기준) 둘레에 놓고 코어 글상자가 비킬 자리(tipAvoid)를 맞춘다. 툴팁 글을 바꾼 뒤(update)와
   * 크기가 바뀐 뒤(31차 — 번역층이 글을 다른 언어로 바꾸면 길이가 달라지는데, update는 바꾸기 전 한국어 글의 크기로 놓아 휴대폰 폭에서 3D 보기 밖으로 잘렸다)
   */
  private placeTipNow(v: LockViewer): void {
    const sp = this.tipAt;
    if (!sp) return;
    const c = v.canvas.getBoundingClientRect();
    const l = this.host.layer.getBoundingClientRect();
    const ox = c.left - l.left;
    const oy = c.top - l.top;
    const w = this.tip.offsetWidth || 80;
    const ht = this.tip.offsetHeight || 20;
    // 코어 글상자가 비킬 자리: 툴팁의 첫 자리(점 오른쪽 아래 — 캔버스 기준). 코어 글상자와 상관없이 정해지므로 서로 쫓지 않는다
    this.tipAvoid = { x: Math.round(sp.x + TIP_GAP), y: Math.round(sp.y + TIP_GAP), width: Math.round(w), height: Math.round(ht) };
    // 코어 거리 글상자(캔버스 기준 — 지난 그리기)를 층 기준으로
    const r = v.measureLabelRect;
    const avoid = r ? { x: ox + r.x, y: oy + r.y, width: r.width, height: r.height } : null;
    // 191차: 떠 있는 것(뷰 큐브·띠 — 마지막 update가 잰 캔버스 기준 coverAvoid)도 층 기준으로 — 툴팁도 비킨다(카메라·툴팁 크기로 다시 놓을 때는 그 값 그대로)
    const covers = this.coverAvoid.map((c) => ({ x: ox + c.x, y: oy + c.y, width: c.width, height: c.height }));
    const at = placeTip(ox + sp.x, oy + sp.y, w, ht, l, avoid, covers);
    this.tip.style.left = `${Math.round(at.x)}px`;
    this.tip.style.top = `${Math.round(at.y)}px`;
  }

  /**
   * 100차: 카메라만 바뀐 그림 뒤(attach — onCameraChange) 툴팁을 붙인 점 p를 다시 투영해 자리만 옮긴다. 글·잠금 상태·상태 줄은 그대로다(미리 보기 값이 같다).
   * 화면 밖으로 나가면 숨기고(update와 같다), 다시 들어오면 같은 글로 보인다. 코어 글상자가 비킬 툴팁 첫 자리도 새 자리로 넘긴다(바뀌었을 때만 — pushAvoid)
   */
  private follow(v: LockViewer, p: readonly number[]): void {
    const sp = v.project(p);
    if (!sp || !sp.onScreen) {
      if (this.tip.hidden) return;
      this.tip.hidden = true;
      this.tipAvoid = null;
    } else {
      this.tip.hidden = false;
      this.tipAt = { x: sp.x, y: sp.y };
      this.placeTipNow(v);
    }
    this.pushAvoid();
  }

  /** 잠금 단추: 잠겼으면 풀고, 아니면 지금 방향(원호 접선이나 코어 — Shift와 같은 판정, 없으면 첫 점 뒤 마지막으로 본 방향)을 잠근다 — 잠글 것이 없으면 맞추는 법을 알린다 */
  toggle(): boolean {
    const v = this.host.viewer();
    if (!v || !this.directing) return false;
    let ok = true;
    if (v.measureInferenceLock) this.unlock();
    else if (!this.lockNow()) {
      ok = false;
      this.noLock();
    }
    this.after();
    return ok;
  }

  /** 화살표: 축(→ X · ← Y · ↑ Z)이나 지금 방향(↓, axis = null). 같은 것으로 이미 잠겼으면 푼다 */
  arrow(axis: 'x' | 'y' | 'z' | null): void {
    const v = this.host.viewer();
    if (!v || !this.directing) return;
    const cur = v.measureInferenceLock;
    if (axis) {
      if (cur?.kind === 'axis' && cur.axis === axis) this.unlock();
      else {
        this.forgetTangent();
        v.setMeasureInferenceLock(axis);
      }
    } else if (cur) this.unlock();
    else if (!this.lockNow()) this.noLock();
    this.after();
  }

  /**
   * Shift 누름(앱 onKey가 코어에 넘기기 전에 — 코어는 잠금이 있으면 Shift를 넘긴다): 커서 아래가 원호 위면 그 접선으로 잠근다.
   * 아니면 아무것도 하지 않는다(코어가 제 판정으로 잠근다)
   */
  shiftDown(): void {
    // 116차: 이 누름을 Shift+Tab 되돌리기에 썼으면 뗄 때까지 다시 잠그지 않는다(다른 Shift 키 — 코어는 눌림이 바뀔 때만 잠근다)
    if (this.shiftUsed) return;
    const v = this.host.viewer();
    const t = this.tangentNow();
    if (!v || !t) return;
    // 116차: 걸기 전 상태(같은 누름의 Shift+Tab이 되돌린다 — undoKey). Tab으로 돌리던 중·가상 커서면 두지 않는다(돌리던 목록이 코어 안에 있어 되살리지 못한다 — 잠근 채)
    const p = this.ptr;
    const u = p && !v.measureHoverSnap?.cycle && !cursorOn(v) ? { t, x: p.x, y: p.y, tangent: this.tangent, result: this.resultTangent } : null;
    if (!this.lockTangent(t)) return;
    this.shiftTangent = true;
    this.undo = u;
    this.after();
  }

  /**
   * 116차 창 keydown(capture — app.ts onKey 다음, 캔버스의 코어 키 듣기 앞): Shift 밖의 키는 받든 받지 않든 그 누름의 되돌리기를 버린다(코어 0.120.0과 같다).
   * 그 키가 같은 누름의 첫 Shift+Tab(캔버스가 받은 키 — Ctrl·Meta·Alt 없음)이고 그 누름이 건 접선 잠금이 그대로면 잠금을 풀고 Tab을 지금 코어에 넘긴다(handleKey — 마우스 Tab 돌리기).
   * 코어가 받으면(걸기 전 그 자리 후보가 둘 이상 — 잠그지 않은 그 자리 후보의 끝) 캔버스 듣기가 같은 Tab을 다시 받지 않게 멈추고 접선 기록을 누르기 전으로 되돌린다 —
   * 그 누름은 뗄 때까지 다시 잠그지 않는다(shiftUsed). 받지 못하면(후보 하나·없음, Esc로 푼 자리) 같은 접선으로 다시 잠가 그 Tab은 코어가 잠근 길로 받는다(지금 그대로)
   */
  private undoKey(e: KeyboardEvent): void {
    if (e.key === 'Shift') return;
    const u = this.undo;
    this.undo = null;
    const v = this.host.viewer();
    const l = v?.measureInferenceLock;
    if (!u || !v || !v.handleKey || !l || e.key !== 'Tab' || !e.shiftKey || e.ctrlKey || e.metaKey || e.altKey || e.defaultPrevented) return;
    if (e.target !== v.canvas || !this.shiftTangent || !this.tangentLocked(l)) return;
    v.setMeasureInferenceLock(false);
    if (!v.handleKey(e)) {
      this.lockTangent(u.t);
      return;
    }
    e.stopPropagation();
    this.tangent = u.tangent;
    this.resultTangent = u.result;
    this.shiftTangent = false;
    this.shiftUsed = true;
    this.after();
  }

  /**
   * 158차 창 keydown(capture — attach, 코어 키 듣기 앞): 3D 보기(캔버스)가 받은 Esc(Ctrl·⌘·Alt 없음, 앱이 막지 않음)에 툴팁이 보이고 찍은 점·끌어온 점이 없으면
   * 툴팁을 거둔다 — 포인터를 옮기지 않고 닫는 길(WCAG 1.4.13). 그 자리의 Esc는 코어가 지울 것이 없어 아무 일도 없었다(점이 있으면 코어 측정 지우기가 거둔다).
   * 막지 않아 코어 Esc(Tab 돌리기 풀기·가상 커서 끄기)는 그대로이고, 그것이 미리 보기를 바꾸면 update가 새 값으로 다시 띄운다(돌리기를 풀면 첫 후보)
   */
  private escTip(e: KeyboardEvent): void {
    const v = this.host.viewer();
    if (e.key !== 'Escape' || e.ctrlKey || e.metaKey || e.altKey || e.defaultPrevented || !v || e.target !== v.canvas || this.tip.hidden) return;
    if (v.measurePointCount || v.measureTrackPoints.length) return;
    this.tipOff = this.tipSaid;
    this.tip.hidden = true;
    this.tipAvoid = null;
    this.tipPoint = null;
    this.pushAvoid();
  }

  /**
   * 203차 창 keydown(capture — attach, 앱 onKey 다음·캔버스의 코어 키 듣기 앞): 가상 커서가 켜진 동안은 화살표가 커서를 옮겨(keys.ts — 캔버스 화살표는 코어 몫)
   * 축을 골라 잠그는 키가 없었다(Shift는 지금 방향만, Alt+화살표는 브라우저 뒤로 가기와 겹침 — README 남은 일 56차). 3D 보기가 받은 X·Y·Z(axisKeyOf — Ctrl·⌘·Alt·Shift 없음,
   * 앱이 막지 않음)는 방향을 잡는 동안(첫 점 뒤) 그 축으로 잠근다 — 커서가 꺼졌을 때 → X · ← Y · ↑ Z와 같은 길(arrow — 같은 축이면 풀고 다른 축이면 바꿈).
   * 받으면 기본 동작을 막는다(Firefox 입력하면 찾기 등). 누른 채 되풀이(repeat)는 막기만 한다(잠갔다 풀었다 하지 않게). 잠근 축·푼 것은 가상 커서 알림 영역에(sayLock)
   * 204차: L(lockKeyOf)은 지금 방향 — 커서가 꺼졌을 때의 ↓와 같은 길(arrow(null) — 잠겼으면 어느 잠금이든 풀고, 아니면 커서 아래 접선·코어 방향·첫 점 뒤 마지막으로 본 방향을 잠그며,
   * 잠글 것이 없으면 띠 위 알림). Shift는 누르는 동안만이고 그동안 화살표는 커서 큰 걸음(코어 keySnapAction)이라, 눌러 잠가 두고 화살표로 잘게 옮기는 키가 없었다.
   * 잠글 것이 없어 앞뒤 모두 잠금이 없으면 가상 커서 알림 영역에는 내지 않는다(「풀었습니다」가 틀린 알림 — 띠 위 알림만)
   */
  private axisKey(e: KeyboardEvent): void {
    const v = this.host.viewer();
    if (!v || e.target !== v.canvas || e.ctrlKey || e.metaKey || e.altKey || e.shiftKey || e.defaultPrevented || !cursorOn(v) || !this.directing) return;
    const a = lockKeyOf(e);
    if (!a) return;
    e.preventDefault();
    if (e.repeat) return;
    const was = this.lock;
    this.arrow(a === 'l' ? null : a);
    if (was || this.lock) this.sayLock();
  }

  /**
   * 203차: X·Y·Z로 잠근 축(LOCK_HINTS — 상태 줄·측정 띠 안내와 같은 글)·푼 것(UNLOCK_SAID)을 가상 커서 알림 영역(keysnap.ts .key-live — 112차 sayCycle과 같은 영역,
   * 번역층이 건너뛰어 지금 언어 글을 넣는다)에. 잠금이 바뀌면 코어가 다음 그림에서 그 커서 자리 후보를 다시 구해 같은 영역에 알린다('refresh' — 「잠근 선 위 …」, 어느 축인지는 없음).
   * 그 알림과 서로 덮지 않게 그 그림 뒤(다음 프레임 — 코어 그리기 요청이 먼저 걸려 먼저 돈다) 잠금 글을 그 알림 앞에 붙인다(다시 구한 알림이 없으면 잠금 글만).
   * 한 프레임 안에 여러 번 누르면 마지막 것만(lockSays)
   */
  private sayLock(): void {
    const live = this.host.layer.querySelector<HTMLElement>('.key-live');
    if (!live) return;
    const was = live.textContent;
    const n = ++this.lockSays;
    requestAnimationFrame(() => {
      if (n !== this.lockSays) return;
      const l = this.lock;
      const head = translate(l ? LOCK_HINTS[l] : UNLOCK_SAID, document.documentElement.lang || 'ko');
      const now = live.textContent;
      const text = now && now !== was ? `${head} · ${now}` : head;
      live.textContent = now === text ? text + NBSP : text;
    });
  }

  /** Shift 뗌·창 흐려짐: Shift로 건 접선 잠금이면 푼다(둘째 점을 찍어 코어가 이미 풀었으면 그대로). 116차: 그 누름의 되돌리기·「되돌리기에 씀」도 끝난다 */
  shiftUp(): void {
    this.undo = null;
    this.shiftUsed = false;
    if (!this.shiftTangent) return;
    this.shiftTangent = false;
    const v = this.host.viewer();
    const l = v?.measureInferenceLock;
    if (v && l && this.tangentLocked(l)) {
      v.setMeasureInferenceLock(false);
      this.forgetTangent();
    }
    this.after();
  }

  /** 지금 방향 잠그기: 커서 아래 원호 접선, 코어가 볼 방향, 지금 볼 것이 없으면 마지막으로 본 것(접선이었으면 접선, 아니면 코어) */
  private lockNow(): boolean {
    const v = this.host.viewer();
    if (!v) return false;
    const t = this.tangentNow() ?? (v.measureHoverLock ? null : this.seenTangent);
    if (t) return this.lockTangent(t);
    this.forgetTangent();
    return v.setMeasureInferenceLock(true);
  }

  /** 원호 접선으로 잠근다(코어 나란함 잠금 — 축과 나란해도 접선 이름으로) */
  private lockTangent(t: V3): boolean {
    const v = this.host.viewer();
    if (!v || !v.setMeasureInferenceLock({ direction: t, kind: 'parallel' })) return false;
    this.tangent = [...t];
    this.resultTangent = [...t];
    return true;
  }

  private unlock(): void {
    this.host.viewer()?.setMeasureInferenceLock(false);
    this.forgetTangent();
  }

  /** 접선 잠금 기록을 지운다(다른 잠금으로 바꾸거나 풀었다) */
  private forgetTangent(): void {
    this.tangent = null;
    this.resultTangent = null;
    this.shiftTangent = false;
  }

  /**
   * 첫 점 뒤 마지막으로 본 잠글 것(코어 lastLockable과 같은 차례 — 원호 접선을 보면 그것, 코어 방향을 보면 코어)과 첫 점이 바뀌었는지.
   * 새 첫 점(다시 재기·둘째 점 뒤 새로)이면 접선 기록을 잊는다(결과를 보이는 동안은 남긴다)
   */
  private track(): void {
    const v = this.host.viewer();
    const pts = (v && v.measureMode ? v.measurePoints : null) ?? [];
    const key = pts.length ? pts[0]!.point.join(',') : '';
    if (key !== this.firstKey) {
      this.firstKey = key;
      this.seenTangent = null;
      if (pts.length === 1) this.forgetTangent();
    }
    if (!v || !this.directing || v.measureInferenceLock) return;
    const t = this.tangentNow();
    if (t) this.seenTangent = t;
    else if (v.measureHoverLock) this.seenTangent = null;
  }

  /** 측정을 끄거나 문서를 바꿨다: 툴팁·알림·접선 기록·코어 글상자가 비킬 자리를 거둔다 */
  reset(): void {
    this.tip.hidden = true;
    this.tipOff = '';
    this.tipAvoid = null;
    this.tipPoint = null;
    this.aimAvoid = null;
    this.coverAvoid = [];
    this.measuring = false;
    this.pushAvoid();
    this.dropFlash(null);
    this.forgetTangent();
    this.undo = null;
    this.seenTangent = null;
    this.firstKey = '';
    this.schedule();
  }

  /**
   * 정밀 조준 십자선을 옮겼다(손가락 자리 — 화면 좌표, 조준을 마치면 null — aim.ts onMove). 십자선을 옮기는 같은 처리 안에서 코어에
   * 십자선(커서 둘레 반지름)과 손가락 둘레 사각형을 넘겨 코어 거리 글상자가 같은 프레임에 비키게 한다
   */
  setAim(finger: { x: number; y: number } | null): void {
    const v = this.host.viewer();
    if (!finger || !v) this.aimAvoid = null;
    else {
      const c = v.canvas.getBoundingClientRect();
      const half = AIM_FINGER_PX / 2;
      this.aimAvoid = { x: Math.round(finger.x - c.left - half), y: Math.round(finger.y - c.top - half), width: AIM_FINGER_PX, height: AIM_FINGER_PX };
    }
    this.pushAvoid();
  }

  /**
   * 측정 중 캔버스 위에 떠 있는 것(코어 뷰 큐브, host.overlays — 측정 띠·해석 판단 띠·재생 띠)의 캔버스 기준 자리(coverRects).
   * 뷰 큐브는 25차부터 코어가 알려 주는 자리(0.23.0 viewCubeRect — 이미 캔버스 기준, 감췄으면 null)를 쓴다. 앱은 CSS로 큐브를 옮기지 않는다
   */
  private covers(v: LockViewer): MeasureLabelRect[] {
    const els: Element[] = [];
    for (const e of this.host.overlays?.() ?? []) if (!(e as HTMLElement).hidden) els.push(e);
    // 192차: 측정 띠 위 알림(띠 상자 밖 — 글이 있을 때만: 빈 알림은 1화소라 coverRects가 빼지 못한다. 띠가 숨으면 크기 0)
    if (this.flash.textContent) els.push(this.flash);
    const cube = v.viewCubeRect;
    if (!cube && !els.length) return [];
    const c = v.canvas.getBoundingClientRect();
    const out = cube ? coverRects({ left: 0, top: 0, width: c.width, height: c.height }, [{ left: cube.x, top: cube.y, width: cube.width, height: cube.height }]) : [];
    return els.length ? [...out, ...coverRects(c, els.map((e) => e.getBoundingClientRect()))] : out;
  }

  /**
   * 코어 글상자가 비킬 자리(손가락·툴팁 첫 자리·떠 있는 것, 조준 중이면 커서 둘레)와 측정 점 표식 비키기(33차 — 코어 0.31.0 points)를 코어에 준다.
   * 35차(코어 0.33.0 snapshotPoints): 그림 저장(PNG — toBlob)의 거리 글상자도 두 측정 점 표식을 덮는 자리만 옮긴다(그림에 없는 앱 영역·커서 둘레는 보지 않는다).
   * 바뀌었을 때만, 측정 중이 아니고 넘길 영역도 없으면 null
   */
  private pushAvoid(): void {
    const v = this.host.viewer();
    if (!v) return;
    const rects = [this.aimAvoid, this.tipAvoid, ...this.coverAvoid].filter((r): r is MeasureLabelRect => !!r);
    const avoid: MeasureLabelAvoid | null = rects.length || this.aimAvoid || this.measuring ? { rects, points: true, snapshotPoints: true, ...(this.aimAvoid ? { pointerRadius: AIM_RETICLE_RADIUS } : {}) } : null;
    const key = JSON.stringify(avoid);
    if (key === this.avoidKey) return;
    this.avoidKey = key;
    v.setMeasureLabelAvoid(avoid);
  }

  /** 자동 확인용: 코어에 준 비킬 자리 */
  get labelAvoid(): MeasureLabelAvoid | null {
    return JSON.parse(this.avoidKey) as MeasureLabelAvoid | null;
  }

  private after(): void {
    this.update();
    this.schedule();
  }

  /** 잠글 방향이 없다는 알림: 측정 띠가 보이면 띠 위에, 아니면(넓은 화면 키보드) 알림 상자로 */
  private noLock(): void {
    const touch = this.host.touch();
    const text = touch ? NO_LOCK_TOUCH : NO_LOCK_MOUSE;
    const bar = this.flash.parentElement;
    if (bar && !bar.hidden && getComputedStyle(bar).display !== 'none') this.showFlash(text, 3200, NO_LOCK);
    else toast(text, 'info', 3200);
  }

  /**
   * 측정 띠 위 알림(kind를 붙이면 그 종류로 거둘 수 있다). 117차: 늘 있는 같은 요소에 글을 넣고 인라인 모습을 지워 클래스 모습(알림 상자)으로 보인다.
   * 134차: 보이는 알림과 같은 원문을 다시 띄우면(잠글 방향 없이 잠금 단추를 두 번 등) 끝에 NBSP를 붙였다 떼어 글을 바꾼다 — 같은 글이면 화면 읽기 프로그램이
   * 다시 읽지 않을 수 있다(sayCycle과 같은 꼴). 화면 번역층이 옮긴 글은 원문과 달라 마지막에 넣은 원문(flashSaid)과 견주고, 번역층은 앞뒤 빈칸을 남기고 옮긴다
   * 230차(WCAG 2.2.1): 잠글 방향·기억할 점이 없다는 경고는 같은 글이 남는 다른 자리가 없는데 포인터를 올려도 ms에 사라졌다 — 알림 상자와 같은 멈춤(dom.ts holdOpen)으로
   * 포인터가 위에 있는 동안은 거두지 않고 떠나면 그때부터 다시 ms(올리지 않으면 전과 같은 시간). 잠금이 걸림·측정 끄기 같은 다른 길(dropFlash)은 그대로 바로 거둔다
   */
  showFlash(text: string, ms = 1600, kind: string | null = null): void {
    this.flashSaid = this.flash.textContent && this.flashSaid === text ? text + NBSP : text;
    this.flash.textContent = this.flashSaid;
    this.flash.removeAttribute('style');
    this.flashKind = kind;
    holdOpen(this.flash, ms, () => this.dropFlash(null));
    // 192차: 알림 자리를 툴팁·코어 글상자가 비키게 다시 놓는다(뒤에 맞추기가 없는 끌어온 점 버튼 길도 — 두 프레임 뒤라 번역층이 옮긴 크기)
    this.schedule();
  }

  /** 알림 거두기(kind를 주면 그 종류일 때만). 117차: 요소는 남기고 글을 비워 화면에서만 감춘다(FLASH_EMPTY) */
  dropFlash(kind: string | null): void {
    if (!this.flash.textContent || (kind !== null && this.flashKind !== kind)) return;
    this.flash.textContent = '';
    this.flash.style.cssText = FLASH_EMPTY;
    this.flashKind = null;
    holdOpen(this.flash, 0, null);
    // 192차: 알림이 지면(시간·잠금이 걸림) 툴팁·코어 글상자를 제자리로
    this.schedule();
  }

  /** 자동 확인용: 툴팁 글(숨었으면 null)·자리, 알림, 잠금, Shift로 잠글 방향, 단추, 첫 점 곡선을 찾은 길(식별자·좌표) */
  snapshot(): { tip: string | null; flash: string | null; lock: LockName | null; hoverLock: LockName | null; button: boolean; tipRect: { x: number; y: number } | null; tangentBy: string | null } {
    const hidden = this.tip.hidden;
    return {
      tip: hidden ? null : this.tip.textContent,
      flash: this.flash.textContent || null,
      lock: this.lock,
      hoverLock: this.hoverLock,
      button: !this.button.hidden,
      tipRect: hidden ? null : { x: parseFloat(this.tip.style.left), y: parseFloat(this.tip.style.top) },
      tangentBy: this.host.tangentBy?.() ?? null,
    };
  }
}
